contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint value) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        bool shouldRevert = value > cBalBefore;
        bool reverted = true;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {} else {
            reverted = false;
        }
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;
        assert(
            (shouldRevert && reverted && cBalAfter == cBalBefore && ownerAfter == ownerBefore && depositsAfter == depositsBefore) ||
            (!shouldRevert && !reverted && cBalAfter == cBalBefore - value && ownerAfter == ownerBefore && depositsAfter == depositsBefore)
        );
    }
}

