pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        bool shouldRevert = value > cBalBefore;
        bool reverted = true;
        try c.withdraw(value) {
            reverted = false;
        } catch {}
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue((shouldRevert && reverted && cBalAfter == cBalBefore && ownerAfter == ownerBefore && depositsAfter == depositsBefore) ||
            (!shouldRevert && !reverted && cBalAfter == cBalBefore - value && ownerAfter == ownerBefore && depositsAfter == depositsBefore));
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
